<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileNicknameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileNicknameAccessor trait.
 *
 * Covers null default, string/VO assignment via withNickname,
 * getNickname/nickname accessors, and isNicknameChanged with/without original.
 */
class UserProfileNicknameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withNickname creates a new instance with the Nickname set
     * from a string value, and getNickname returns the primitive string.
     */
    public function testWithNicknameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileNicknameAccessorUnitTest();

        // Act
        $result = $holder->withNickname('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getNickname());
    }
    /**
     * Asserts that withnickname has access to the value object
     * from a string value, and getNickname returns the primitive string.
     */
    public function testWithNicknameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileNicknameAccessorUnitTest();

        // Act
        $result = $holder->withNickname('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->nickname()->value());
    }
    public function testChangedNickname(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileNicknameAccessorUnitTest();
        $original = $holder->withNickname('one');
        $same = $holder->withNickname('one');
        $modified = $holder->withNickname('other');

        // Act
        $unchanged = $holder->isNicknameChanged();
        $withSame = $original->isNicknameChanged($same);
        $withDiferent = $original->isNicknameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileNicknameAccessorUnitTest
{
    use UserProfileNicknameAccessor;
}
